#!/usr/bin/env python3
"""Feature-agent prompts for one coverage wave.

    wave-prompts.py <wave-dir> <suffix>

Writes <wave-dir>/prompt-<agent>.txt for each agent in OWNS. Edit OWNS
(one line per agent: what it owns, shown to every agent) and EXTRA (the
agent's own priorities) per wave; the agent names must match the table
in wave-lists.py. <suffix> is appended to branch names so they do not
clash with an earlier wave's branches.
"""
import sys

W, SUF = sys.argv[1], sys.argv[2]
OWNS = {
    'wording': 'cards a card agent reported as a renderer near-miss (`RENDER:`) or as gating with the wrong meaning (`MEANING:`), and template drafts that render with a mismatch: renderer wording, pronouns for legends ("him", "she", "they"), and binding of references in the compiler; and the open wrong-meaning forms in `KNOWN-ISSUES.md` section 2',
    'permissions': 'permissions to cast or play: temporary and static permissions (cast from exile or a graveyard for a time, free casts with a mana-value cap, "you may cast spells from your hand without paying", "look at the top card of your library any time", play from the top of the library for a turn), face-down exile with "look at and play", abilities granted to cards in a hand or graveyard (flashback, warp), and a bare "if you cast it" on a permanent other than the source',
    'counts': 'counts, amounts and conditions still reported missing ("half", "greatest", "difference", "if X is N or more", "where X is ..." on costs and searches, numbers of colors or card types, things that happened this turn), and anything about a card on these lists that no other agent owns',
    'perf': 'per-game throughput only (profile-guided; no behaviour change, no cards)',
}
STD = 'This is a small wave before a usage reset. Standard (79.4%, 1,065 cards uncovered) is the first target: work your Standard lines first, grouped by what is missing, and build the groups in order of cards unlocked; then Pauper lines; leave Modern-only lines. Stop when the remaining groups are one card each and you have used about 350k tokens.'
EXTRA = {
    'wording': STD + """ Each line on your list says what the renderer printed and what the Oracle text says, or which reference bound to the wrong object. These are the cheapest cards in the backlog: the engine can usually already do what the card does. For a `RENDER:` line fix the renderer (or add the alternative phrase to the parser) and write the card with a scenario. For a `MEANING:` line make the compiler bind the form correctly, or reject it, and add a scenario that checks the amount or the object. The ninth wave's retry batches added about 60 fresh `RENDER:` lines for Standard cards (the newest reports, `report-m0*.tsv` in the reports directory `{W}/../agents/`): start with those. Then the open entries of `KNOWN-ISSUES.md` section 2 ("Found in the ninth wave" and "Found in the eighth wave and still open"), including the form the template author writes for Through the Breach ("you may put a creature card from your hand onto the battlefield. That creature gains haste. Sacrifice that creature at the beginning of the next end step."): bind each correctly or make the compiler reject it, and list what you fixed under `Fixed` in your notes.""",
    'permissions': STD + """ Read your list and group it; the reports name, among others: Omniscience ("cast spells from your hand without paying their mana costs"), "the next creature spell may be cast without paying", "cast up to two spells from among the exiled cards" free, a once-each-turn free cast from exiled cards with a mana-value cap, "you may cast it from your graveyard as an Adventure until the end of your next turn", a temporary "play lands and cast spells from the top of your library", "look at the top card of your library any time", "Until the end of your next turn, you may cast that card" (wording order), face-down exile with "you may look at and play that card for as long as it remains exiled", flashback or warp granted to cards in a graveyard or hand (Iroh, Tannuk, Lorehold), "mill a card; you may play that card this turn" (gates and gives no permission: `KNOWN-ISSUES.md` section 2), and a bare "if you cast it/them" on an entering permanent that is not the source (The Sibsig Ceremony, Nine-Lives Familiar, Territory Forge; also section 2). The impulse list (`PlayableExile`) already carries temporary permissions for exile and graveyard cards: extend it; a new way to cast a card from hand must be added to the list behind `CardDef::other_casts`.""",
    'counts': STD + """ Your list is long and mostly one card per form, so pick by cost: forms the engine can already compute and only the language lacks come first. The reports name, among others: "half" (their library, the creatures, X), "if X is 10 or more" / "if X is 2 or less" and "3 minus X", "{X} less to cast, where X is a power or count" on one spell, a search or dig count from a variable, "the greatest mana value among cards in your graveyard / discarded this way", "the difference between its power and toughness", "power greater than its base power", the number of a spell's colors and of card types among permanents or spells cast, "creatures that left the battlefield this turn", "counters put on this creature this turn", "you sacrificed a permanent this turn", "an opponent has more cards in hand", "damage dealt to it this turn", "for each opponent who lost life / didn't discard", mana value "4 or 5" (currently parsed silently as 4: make it a range or an error), "explores X times" / "proliferate X times", "max of 2 and a count". A count used in a static ability must work in the layer system too (`per_count` in `crates/mtg-core/src/layers.rs` must read `Work`, never `GameState::characteristics`: a debug build panics on re-entry), and `CountExpr::in_static` must classify every count you add.""",
}
for k in EXTRA:
    o = '\n'.join(f'- {n}: {d}' + (' (you)' if n == k else '') for n, d in OWNS.items())
    b = f'feature-{k}{SUF}'
    p = f"""You are a feature agent on a Rust Magic: The Gathering rules engine. Your worktree may have been created from an old commit: first run `git checkout -B {b} main` so you start from current main (if git refuses because the branch is checked out in another worktree, use `{b}-b` and say so). Then read `scripts/coverage/feature-brief.md` in your working directory (your git worktree) and follow it exactly. Your notes file (see its section on known issues) is `{W}/notes-{k}.md`.

YOUR ASSIGNMENT (branch name `{b}`): {OWNS[k]}.

{EXTRA[k].replace('{W}', W)}

Your card list is `{W}/lists/{k}.tsv` (card name, formats, and what a card-authoring agent or the template author reported, Pauper cards first, then Standard; a card may need other things too: skip those and say which). Many lines are from earlier waves and may work now. `cargo run -q --release -p mtg-cards -- author --format pauper --verbose` (and `standard`, `modern`; give the modern run a long timeout) lists skipped cards with reasons. Where the wording is regular, add a template to `crates/mtg-cards/src/author.rs`. Do not add the cards named in `{W}/batches/all.txt`: card agents are writing those on main.

OTHER AGENTS working in parallel own these; do not build your own version of any of them, skip cards needing them and say so:
{o}
- no card agents are running this wave

A card counts only if the gate says Match AND a scenario shows it behaves as the Oracle text says, checking amounts and targets. If a form gates Match but means the wrong thing, do not add the card; put it in your notes file under `New`.
Each new form needs DSL syntax, exact Oracle rendering, SYNTAX.md, and scenarios.

Merge hazards: if you take a free bit (`DefFlags`, `GameObject::marks`, `CastInfo`) or add a `Keyword` (`Keyword::ALL` has a fixed length) or a `CounterKind` (`CounterKind::NAMED` has a fixed length), say so in your final reply, since another branch may take the same one. If you add a variant to an enum that is matched exhaustively elsewhere (`CountExpr`, `Effect`, `Trigger`) or change a function's signature, say so too. A new way to cast a card from hand must be added to the list behind `CardDef::other_casts` in `CardPool::add`. You may add a line form to the scenario runner (`crates/mtg-scenario`) if a card cannot be tested without it; do not change what an existing line does, and name the addition in your final reply. Throughput matters: a check you add to a hot path (priority, state-based actions, `characteristics`, every event) must cost nothing when no card in the game uses the feature (gate it on a pool- or state-level flag rather than scanning the battlefield).

Commit as you go (one commit per feature or bug). Write each commit message to a file and commit with `git commit -F <file>`. End each commit message with `Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>`. Before your last commit run `cargo fmt`, `cargo clippy -q --workspace`, the gate, the scenarios (release, and once with a debug build: `cargo build -p mtg-cli && target/debug/mtg scenario`), and `timeout 2400 cargo test --workspace` (it includes a format/parse round-trip over the whole corpus). Wrap every cargo test run in `timeout`. Give every long command a `timeout` and never wait on one with an unbounded loop: a game that loops shows up only as silence (`scripts/fuzz-random.sh` kills and reports a run after FUZZ_TIMEOUT seconds). When you wait for a background command, never poll with `pgrep -f "<its command line>"`: that matches the polling shell itself and never ends; wait on the command's exit instead. Delete your worktree's `target/` when everything is committed. Final reply: branch name, commit hashes, what you implemented, number of cards added per item, anything left out, bits, keywords, counter kinds, enum variants or signatures you took or changed, and any ENGINE BUG you found."""
    open(f'{W}/prompt-{k}.txt', 'w').write(p)
    print(k, len(p))
